let landFarbe;
let erthSize;
let lerpingProgress = 0;
let lerpingSpeed = 0.005/5;
let increaseSize = true;
let randomSteps;
let maxRotationDegrees = 150;
let rotationSpeedX = 0.005;
let rotationSpeedY = 0.005;
