function setup() {
  createCanvas(WIDTH, HEIGHT, WEBGL);
  clear();
  erthSize = 1;
  zoom = erthSize;
  currentRotationX = 0;
  currentRotationY = 0;
  randomSteps = 80; //R.random_num(40, 160);
  wasser = R.random_num(85, 95);
  strand = 120;
   land = 200; //R.random_num(120, 180);
  zufall = 167;
  minus = 0;
  plus = 0;

  setTimeout(setPlusTo200, 12000); // 5000 Millisekunden entsprechen 5 Sekunden

  setTimeout(setSpin, 6000); // 6000 Millisekunden entsprechen 5 Sekunden

// Wähle zufällig eine Farbe aus der Palette
  const selectedColorIndex = floor(R.random_num(0, colors.length));
