function setPlusTo200() {



  if (R.random_bool(0.5)) {
    currentRotationX = 5;
   
    
  } else {
    
    currentRotationY = 5;
    
  }
  
  plus = R.random_num(200, 700);
  minus = R.random_num(-100, -500);

   
}

function draw() {
  background(0);
  scale(0.9);
  lerpingProgress += lerpingSpeed;

  if (!mousePressedForRotation) {
    if (increaseSize) {
      erthSize = min(lerp(erthSize, 0.7, lerpingProgress), 0.7);
    } else {
      erthSize = max(lerp(erthSize, 0.5, lerpingProgress), 0.5);
    }

    if (lerpingProgress >= 1) {
      lerpingProgress = 0;
      increaseSize = !increaseSize;
    }
  }

  landFarbe = lerpColor(color(R.random_choice(colors).farbwert), color(R.random_choice(colors).farbwert), lerpingProgress);

  if (mousePressedForRotation) {
    let mouseXDiff = mouseX - pmouseX;
    let mouseYDiff = mouseY - pmouseY;

    let targetRotationX = radians(mouseYDiff * 10);
    let targetRotationY = radians(mouseXDiff * 10);

    // Interpoliere die Rotation schrittweise
    currentRotationX = lerp(currentRotationX, targetRotationX, 0.05);
    currentRotationY = lerp(currentRotationY, targetRotationY, 0.05);
  } else {
    let rotationX = radians(R.random_num(-maxRotationDegrees, maxRotationDegrees)) * rotationSpeedX;
    let rotationY = radians(R.random_num(-maxRotationDegrees, maxRotationDegrees)) * rotationSpeedY;
    currentRotationX = lerp(currentRotationX, rotationX, 0.05);
    currentRotationY = lerp(currentRotationY, rotationY, 0.05);
  }

  // Wende die Rotation an
  rotateX(-currentRotationX);
  rotateY(-currentRotationY);

  drawTerrain();
}


function drawTerrain() {
  let radius = min(width, height) * (erthSize);

  let numSteps = randomSteps;
  let stepSize = radius / numSteps*2;

  let centerX = 0;
  let centerY = 0;

  push();

  for (let y = 0; y < numSteps; y++) {
    for (let x = 0; x < numSteps; x++) {
      let posX = centerX - radius / 2 + x * stepSize + stepSize / 2;
      let posY = centerY - radius / 2 + y * stepSize + stepSize / 2;

      if (dist(posX, posY, centerX, centerY) <= radius / 2) {
        let noiseVal = noise((posX + xOffset) * noiseScale, posY * noiseScale) * zufall;

        if (noiseVal < wasser) {
          let lerpedColor = lerpColor(color(0, 200, 200), wasserFarbe, map(noiseVal, 0, wasser, 0, 1));
          fill(lerpedColor);
        } else if (noiseVal < strand) {
          let lerpedColor = lerpColor(wasserFarbe, landFarbe, map(noiseVal, wasser, strand, 1, 1));
          fill(lerpedColor);
        } else if (noiseVal < land) {
          let colorValue = map(noiseVal, strand, land, 50, 255);
          fill(colorValue);
        }

        stroke(0);

        let size = stepSize;
        let z = map(noiseVal, 0, zufall, minus, plus);

       

        push();
        translate(posX, posY, z);
        box(size);
        pop();

        boxCount++; // Erhöhe den Zähler für die Anzahl der gezeichneten Boxen
        
      }
    }
  }

  if (!countedBoxes) { // Wenn die Boxen noch nicht gezählt wurden
    console.log("Anzahl der Boxen:", boxCount); // Gebe die Anzahl der Boxen in der Konsole aus
    if (boxCount < 1000) {
      console.log("Status: Small");
    } else {
      console.log("Status: Big");
    }
    countedBoxes = true; // Markiere, dass die Boxen gezählt wurden
  }

  pop();
}

