function mouseWheel(event) {
  // Erhöhe oder erniedrige die Werte von plus und minus basierend auf dem Mausrad-Ereignis
  if (event.delta > 0) {
    plus += 50; // Wert erhöhen
    minus += 50; // Wert erhöhen
  } else {
    plus -= 50; // Wert erniedrigen
    minus -= 50; // Wert erniedrigen
  }
  
  // Begrenze die Werte von plus und minus zwischen bestimmten Grenzen
  plus = constrain(plus, 0, 400);
  minus = constrain(minus, -1200, 0);

  return false; // Verhindere Standard-Scrollverhalten der Seite
}



function windowResized() {
